package cn.course.community;
import java.util.*;
import java.security.Principal;
import org.springframework.stereotype.Service;
import org.springframework.web.bind.annotation.*;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import static cn.course.community.ApiError.fail;
@Service
public class EvidenceWorkbench {
 final Store s;final CommunityService domain;EvidenceWorkbench(Store s,CommunityService domain){this.s=s;this.domain=domain;}
 static final String FROM=" FROM evidence x JOIN submission v ON v.id=x.submission_id JOIN entry e ON e.id=v.entry_id JOIN assignment a ON a.id=e.assignment_id JOIN app_user u ON u.id=e.author_id ";
 String select(){return "SELECT x.*,e.author_id,u.display_name AS author_name,v.title,v.version_no,a.id AS assignment_id,a.title AS assignment_title,"+
 "(SELECT COUNT(*) FROM verification z WHERE z.evidence_id=x.id) AS record_count,"+
 "(SELECT COUNT(*) FROM evaluation g WHERE g.submission_id=v.id AND g.active=TRUE) AS graded,"+
 "(SELECT COUNT(*) FROM verification z WHERE z.evidence_id=x.id AND (z.verifier_role='TEACHER' OR (z.verifier_role IS NULL AND EXISTS(SELECT 1 FROM course_member cm WHERE cm.course_id=a.course_id AND cm.user_id=z.verifier_id AND cm.role='TEACHER')))) AS teacher_decided";}
 void flags(Map<String,Object> row,long uid,String role){long id=s.id(row,"id");boolean own=s.id(row,"author_id")==uid,graded=((Number)row.get("graded")).intValue()>0,teacher=role.equals("TEACHER");boolean checked=s.db.queryForObject("SELECT COUNT(*) FROM verification WHERE evidence_id=? AND verifier_id=?",Integer.class,id,uid)>0;String blocked=graded?"已评分，核验已冻结":own?"作者不能核验自己的证据。":!teacher&&((Number)row.get("teacher_decided")).intValue()>0?"教师已裁定，本条不再接受同伴核验。":!teacher&&checked?"你已核验这条证据；需要改判请联系教师。":"";row.put("can_verify",blocked.isEmpty());row.put("blocked_reason",blocked);row.put("my_verified",checked);row.put("locked",graded);}
 public Map<String,Object> list(long cid,long uid,String q,String state,String relation,long aid,int page){String role=s.role(cid,uid);if(q.length()>80||!Set.of("","PENDING","PASS","FAIL","DISPUTED").contains(state)||!Set.of("ALL","MINE","TODO","DONE").contains(relation)||aid<0||page<1||page>100000)throw fail(400,"证据查询参数不正确");var args=new ArrayList<Object>();args.add(cid);// 只列每篇作品最新版本上的证据：旧版本的证据已被新版本取代，核验它没有意义。
  String where="a.course_id=? AND NOT EXISTS(SELECT 1 FROM submission nv WHERE nv.entry_id=v.entry_id AND nv.version_no>v.version_no)";if(aid>0){where+=" AND a.id=?";args.add(aid);}if(!q.isBlank()){String term="%"+q.trim().toLowerCase(Locale.ROOT).replace("!","!!").replace("%","!%").replace("_","!_")+"%";where+=" AND (LOWER(x.source_title) LIKE ? ESCAPE '!' OR LOWER(x.claim_text) LIKE ? ESCAPE '!' OR LOWER(v.title) LIKE ? ESCAPE '!' OR LOWER(u.display_name) LIKE ? ESCAPE '!')";for(int i=0;i<4;i++)args.add(term);}if(!state.isEmpty()){where+=" AND x.state=?";args.add(state);}if(relation.equals("MINE")){where+=" AND e.author_id=?";args.add(uid);}if(relation.equals("DONE")){where+=" AND EXISTS(SELECT 1 FROM verification z WHERE z.evidence_id=x.id AND z.verifier_id=?)";args.add(uid);}if(relation.equals("TODO")){where+=" AND e.author_id<>? AND NOT EXISTS(SELECT 1 FROM evaluation g WHERE g.submission_id=v.id AND g.active=TRUE)";args.add(uid);if(!role.equals("TEACHER")){where+=" AND NOT EXISTS(SELECT 1 FROM verification z WHERE z.evidence_id=x.id AND (z.verifier_id=? OR z.verifier_role='TEACHER' OR (z.verifier_role IS NULL AND EXISTS(SELECT 1 FROM course_member cm WHERE cm.course_id=a.course_id AND cm.user_id=z.verifier_id AND cm.role='TEACHER'))))";args.add(uid);}}
 int total=s.db.queryForObject("SELECT COUNT(*)"+FROM+"WHERE "+where,Integer.class,args.toArray());args.add(20);args.add((page-1)*20);var rows=s.db.queryForList(select()+FROM+"WHERE "+where+" ORDER BY CASE x.state WHEN 'DISPUTED' THEN 0 WHEN 'PENDING' THEN 1 ELSE 2 END,x.id DESC LIMIT ? OFFSET ?",args.toArray());for(var row:rows)flags(row,uid,role);var counts=s.db.queryForList("SELECT x.state,COUNT(*) AS total"+FROM+"WHERE a.course_id=? AND NOT EXISTS(SELECT 1 FROM submission nv WHERE nv.entry_id=v.entry_id AND nv.version_no>v.version_no) GROUP BY x.state",cid);return Map.of("items",rows,"counts",counts,"total",total,"page",page,"pageSize",20);}
 public Map<String,Object> detail(long id,long uid){var row=s.one(select()+",a.course_id"+FROM+"WHERE x.id=?",id);String role=s.role(s.id(row,"course_id"),uid);flags(row,uid,role);var v=domain.submission(s.id(row,"submission_id"));var anchors=domain.anchors(domain.decode(v.get("content_json")));row.put("paragraph_text",anchors.getOrDefault((String)row.get("paragraph_id"),""));row.put("records",domain.verifications(id,uid));boolean read=true;try{domain.visible(v,uid);}catch(ApiError.Failure e){if(e.status==403)read=false;else throw e;}row.put("can_read_submission",read);return row;}
 public record Decision(@NotBlank @Pattern(regexp="PASS|FAIL") String verdict,@NotBlank @Size(max=2000) String reason,@NotNull @Min(0) Integer expectedCount){}
}
@RestController @RequestMapping("/api")
class EvidenceWorkbenchController {
 final EvidenceWorkbench w;final Store s;final CommunityService domain;EvidenceWorkbenchController(EvidenceWorkbench w,Store s,CommunityService domain){this.w=w;this.s=s;this.domain=domain;}
 @GetMapping("/courses/{cid}/evidence-workbench") public Object list(@PathVariable long cid,@RequestParam(defaultValue="") String q,@RequestParam(defaultValue="") String state,@RequestParam(defaultValue="ALL") String relation,@RequestParam(defaultValue="0") long assignmentId,@RequestParam(defaultValue="1") int page,Principal p){return w.list(cid,s.uid(p.getName()),q,state,relation,assignmentId,page);}
 @GetMapping("/evidence/{id}/review") public Object detail(@PathVariable long id,Principal p){return w.detail(id,s.uid(p.getName()));}
 @PostMapping("/evidence/{id}/decisions") public Object decide(@PathVariable long id,@Valid @RequestBody EvidenceWorkbench.Decision r,Principal p){domain.verify(id,r.verdict(),r.reason(),s.uid(p.getName()),r.expectedCount());return Map.of("ok",true);}
}
